(2456273, 337287, 52092, '<td valign="top">i dont understand the title, but very nice perspective and composition.</td>', 'i dont understand the title, but very nice perspective and composition.', '2006-05-25 12:16:08.000000', NULL, 1),
(2456274, 338249, 52114, '<td valign="top">Great composition and the shadows pull the picture together.</td>', 'Great composition and the shadows pull the picture together.', '2006-05-25 12:16:46.000000', NULL, 1),
