(2468452, 337908, 55767, '<td valign="top">nice capture of the double rainbow</td>', 'nice capture of the double rainbow', '2006-05-30 11:57:40.000000', NULL, 1),
(2468470, 337995, 55767, '<td valign="top">your picture would be more powerful if it had been submitted at the maximum size.</td>', 'your picture would be more powerful if it had been submitted at the maximum size.', '2006-05-30 12:08:29.000000', NULL, 1),
(2468473, 337951, 55767, '<td valign="top">great capture!</td>', 'great capture!', '2006-05-30 12:09:19.000000', NULL, 1),
(2468501, 337511, 45790, '<td valign="top">I always rate well gutsy entries like this, however, as you probably know, it is doomed to failure and probably won''t even get the "brown ribbon" because of people who like the humor, such as me!</td>', 'I always rate well gutsy entries like this, however, as you probably know, it is doomed to failure and probably won''t even get the "brown ribbon" because of people who like the humor, such as me!', '2006-05-30 12:23:26.000000', NULL, 1),
(2468503, 337934, 45790, '<td valign="top">Very strong and intense. I like it!</td>', 'Very strong and intense. I like it!', '2006-05-30 12:24:22.000000', NULL, 1),
(2468510, 337991, 45790, '<td valign="top">Good, moody lighting and composition. One can''t tell if she failed to get pregnant or contraceptive failed! The pregnency test is perhaps a bit too subtle here -- I must admit that at first glance I thought "constipation".</td>', 'Good, moody lighting and composition. One can''t tell if she failed to get pregnant or contraceptive failed! The pregnency test is perhaps a bit too subtle here -- I must admit that at first glance I thought "constipation".', '2006-05-30 12:27:41.000000', NULL, 1),
(2468512, 337940, 45790, '<td valign="top">Fantastic tone contrast. Sharp, sepia-tone conversion works well.</td>', 'Fantastic tone contrast. Sharp, sepia-tone conversion works well.', '2006-05-30 12:30:17.000000', NULL, 1),
(2468516, 337255, 45790, '<td valign="top">The lighting is working against you here. Top of tree is overexposed and foreground is dark. Maybe fill flash would help (or photographing at different time of day.)</td>', 'The lighting is working against you here. Top of tree is overexposed and foreground is dark. Maybe fill flash would help (or photographing at different time of day.)', '2006-05-30 12:33:03.000000', NULL, 1),
(2468518, 337312, 45790, '<td valign="top">Yep the drive has failed! I don''t see what you are trying to accomplish with the "letterbox" frame.</td>', 'Yep the drive has failed! I don''t see what you are trying to accomplish with the "letterbox" frame.', '2006-05-30 12:34:28.000000', NULL, 1),
(2468520, 336332, 45790, '<td valign="top">Sad subject. Well photographed, but I really don''t want to look at it.</td>', 'Sad subject. Well photographed, but I really don''t want to look at it.', '2006-05-30 12:35:35.000000', NULL, 1),
(2468526, 337908, 45790, '<td valign="top">Yes the sensor dust is a failure, but why is the sky so much lighter under the rainbow? This doesn''t look natural.</td>', 'Yes the sensor dust is a failure, but why is the sky so much lighter under the rainbow? This doesn''t look natural.', '2006-05-30 12:37:29.000000', NULL, 1),
(2468529, 337981, 45790, '<td valign="top">Beautiful colors with great composition. I like all the angles.</td>', 'Beautiful colors with great composition. I like all the angles.', '2006-05-30 12:39:35.000000', NULL, 1),
