INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2468545, 337687, 45790, '<td valign="top">I like the idea, the lighting and the use of color, but I''m torn about the tilt. While this does have the flower straight and perhaps emphasizes the "still broken" nature of the vase, I think "of course it fell and broke -- it''s resting on a very tilted surface!" At least for me, I think having the vase straight (and rotated a bit to show the break more) and the flower being tilted would be better.</td>', 'I like the idea, the lighting and the use of color, but I''m torn about the tilt. While this does have the flower straight and perhaps emphasizes the "still broken" nature of the vase, I think "of course it fell and broke -- it''s resting on a very tilted surface!" At least for me, I think having the vase straight (and rotated a bit to show the break more) and the flower being tilted would be better.', '2006-05-30 12:47:50.000000', NULL, 1),
(2468558, 337835, 45790, '<td valign="top">And the funny thing is -- it doesn''t look half bad! You''ve turned Yet Another Flower Shot into something interesting.</td>', 'And the funny thing is -- it doesn''t look half bad! You''ve turned Yet Another Flower Shot into something interesting.', '2006-05-30 12:57:06.000000', NULL, 1),
(2468561, 337461, 45790, '<td valign="top">I like the cigarette being in sharper focus than the smoker.</td>', 'I like the cigarette being in sharper focus than the smoker.', '2006-05-30 12:58:28.000000', NULL, 1),
(2468567, 338306, 45790, '<td valign="top">This would have been a fine picture if you made use of the 640 pixel maximum dimension you are allowed. (I''m sure other people will point this out, too.)</td>', 'This would have been a fine picture if you made use of the 640 pixel maximum dimension you are allowed. (I''m sure other people will point this out, too.)', '2006-05-30 13:01:17.000000', NULL, 1),
(2468574, 336800, 45790, '<td valign="top">Interesting idea, but doesn''t work because the only thing in focus -- the monitor, doesn''t show enough detail to imply "success". Also, wouldn''t he have colapsed in front of the monitor and not on the other side of the desk?</td>', 'Interesting idea, but doesn''t work because the only thing in focus -- the monitor, doesn''t show enough detail to imply "success". Also, wouldn''t he have colapsed in front of the monitor and not on the other side of the desk?', '2006-05-30 13:03:24.000000', NULL, 1),
(2468578, 337870, 45790, '<td valign="top">Over-exposed, seemingly out of focus, image too small, and dreadful title. Sorry.</td>', 'Over-exposed, seemingly out of focus, image too small, and dreadful title. Sorry.', '2006-05-30 13:05:39.000000', NULL, 1),
(2468579, 338081, 45790, '<td valign="top">I think you took the picture slightly too soon. Seeing the balloon starting to burst would have been an exciting picture.</td>', 'I think you took the picture slightly too soon. Seeing the balloon starting to burst would have been an exciting picture.', '2006-05-30 13:06:49.000000', NULL, 1),
(2468585, 337947, 45790, '<td valign="top">Good idea and fair execution, but I wonder why she is taking her time to light up a cigarette?</td>', 'Good idea and fair execution, but I wonder why she is taking her time to light up a cigarette?', '2006-05-30 13:10:59.000000', NULL, 1),
(2468586, 337793, 50583, '<td valign="top">Excellent photo, but...not seeing how it fits into the challenge.  8</td>', 'Excellent photo, but...not seeing how it fits into the challenge.  8', '2006-05-30 13:11:24.000000', NULL, 1),
(2468588, 338249, 45790, '<td valign="top">It makes sense to me except for that can of paint -- better off without it.</td>', 'It makes sense to me except for that can of paint -- better off without it.', '2006-05-30 13:13:17.000000', NULL, 1),
(2468590, 338126, 50583, '<td valign="top">Haha, great!</td>', 'Haha, great!', '2006-05-30 13:13:57.000000', NULL, 1),
