(2471557, 337793, 36060, '<td valign="top">Congratulations on your top 10 finish. Brilliant shot!</td>', 'Congratulations on your top 10 finish. Brilliant shot!', '2006-05-31 11:06:21.000000', NULL, 0),
(2471563, 337971, 36060, '<td valign="top">Congratulations on your top 10 finish. Great shot!</td>', 'Congratulations on your top 10 finish. Great shot!', '2006-05-31 11:07:15.000000', NULL, 0),
